insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Computer Vision Research','A repository dedicated to my research, implementation and learning about the groundbreaking advancements in Computer Vision. The repository comprises implementation — from scratch — of various prominent Computer Vision architectures, which includes: Vision Transformer, MobileNet, ResNet, EfficientNet, et al. The tasks covered span across image classification, object segmentation, detection and generative models, such as Diffusion models and Generative Adversarial Networks (GANs).','https://github.com/TolaniSilas/Computer-Vision-Research','/images/cv-image.png','','',1,true,array['AI & ML']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Computer Vision Research');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Mini GPT','Implemented Generative Pretrained Transformer (GPT) models (e.g., GPT-2, GPT-3) for experimental purposes to gain a deeper understanding of the underlying mechanisms of this technology. The model architecture is inspired by a major breakthrough in deep learning: the self-attention mechanism introduced in ''Attention Is All You Need'' by Vaswani et al. It employs a decoder-only Transformer design and incorporates Byte Pair Encoding (BPE) tokenization as its robust text-preprocessing technique.','https://github.com/TolaniSilas/Mini-GPT','/images/llm-image.png','','',2,true,array['AI & ML']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Mini GPT');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Real-Time Currency Analyst Agent','A conversational, financial intelligence AI Agent specialized in analyzing currencies. It fetches real-time exchange rate data and interprets currency relationships at real-time (the current moment). It responsibility is also to provide clear and concise insights for users seeking to understand the relative strength of currencies across various countries or perform instant conversions between different currencies.','https://github.com/TolaniSilas/genai_works/tree/main/src/currency_analyst_agent','/images/currency-image.png','','',4,true,array['AI & ML','Backend Development']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Real-Time Currency Analyst Agent');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Web3 Semantic Search','This is a decentralized content retrieval system in which users upload content - such as images and blogs - that can later be retrieved by other users using natural-language search (via queries or prompts). It was developed on Camp Network - a Layer-1 blockchain built to modernize intellectual property (IP) infrastructure and power the next generation of AI Agents on verifiable IP.','https://github.com/TolaniSilas/web3-semantic-search','/images/web3-semantic.png','','',5,true,array['AI & ML','Backend Development']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Web3 Semantic Search');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Automatic Detection of Diabetic Retinopathy','An end-to-end AI-driven software system for early detection of Diabetic Retinopathy (DR) using deep learning and computer vision techniques. This project analyzes retinal fundus images to automate diagnosis, improving accuracy, speed, and accessibility of diabetic eye screening for ophthalmologists.','https://diabetic-retinopathy-web.streamlit.app/','/images/ai-as-a-doctor.png','','',3,true,array['AI & ML','Web Development','Backend Development']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Automatic Detection of Diabetic Retinopathy');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Recipe Site Traffic','An end-to-end ML system from problem formulation to model deployment via Docker; it also step forward to cover data drift and model monitoring. The product team at Tasty Bytes needs a data-driven assistance in the decision-making process for selecting which recipes to feature on the homepage so they can maximize high-traffic recipes and minimize low-traffic ones, with a target of correctly identifying popular recipes around 80% of the time, thereby boosting subscriptions.','https://github.com/TolaniSilas/Recipe-Site-Traffic','/images/recipe-traffic-image.png','','',6,true,array['Backend Development','AI & ML','Web Development']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Recipe Site Traffic');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'project','Loan Eligibility App','A machine learning web application developed for Dream Housing Finance to automate real-time loan eligibility assessments. It analyzes customer data, validates financial metrics, and predicts approval outcomes with high accuracy, streamlining decision-making for the company.','https://dreamhousingfinance.onrender.com/','/images/loan-eligibility.png','','',7,true,array['Backend Development','AI & ML','Web Development']::text[] where not exists (select 1 from public.portfolio_content where kind='project' and title='Loan Eligibility App');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'article','Getting Started with LLMs: How to Serve LLM Applications as API Endpoints with FastAPI in Python','Large Language Models (LLMs) are leading advancements in Generative AI, revolutionizing how machines comprehend and produce human-like text. In this blog, we''ll explore how APIs short for Application Programming Interfaces, enable applications to harness the power of LLMs.','https://medium.com/@tolanisilas3606/getting-started-with-llms-how-to-serve-llm-applications-as-api-endpoints-with-fastapi-in-python-af015399ef3e','','','August 20, 2024',0,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='article' and title='Getting Started with LLMs: How to Serve LLM Applications as API Endpoints with FastAPI in Python');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'publication','Publication 1','Bakare, A. O., Seriki, K. T., Emmanuel, F. O., Osunba, S. T., Ayoigbala, S. E., & K. J. Oshile. Using Convolutional Neural Network for the Detection of Offshore and Onshore Oil Spills. Paper presented at the SPE Nigeria Annual International Conference and Exhibition, Lagos, Nigeria, August 2025.','https://doi.org/10.2118/228732-MS','','','',0,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='publication' and title='Publication 1');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'publication','Publication 2','Kolade, O., Adeleke, V. A., Ojo, S. D., Osunba, S., Anifowose, O., and K. Abdul. Electric Vehicles vs. Biofuels: A Review of Decarbonization in Transportation. Paper presented at the SPE Nigeria Annual International Conference and Exhibition, Lagos, Nigeria, August 2025.','https://doi.org/10.2118/228753-MS','','','',1,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='publication' and title='Publication 2');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'publication','Publication 3','Bakare, A. O., Seriki, K. T., & Osunba, S. M. (2025). Predicting Proton Exchange Membrane Fuel Cell Performance through Advanced Machine Learning Techniques: A Comparative Analysis of Ensemble Techniques. Scientia. Technology, Science and Society, 2(8), 73-86.','https://doi.org/10.59324/stss.2025.2(8).07','','','',2,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='publication' and title='Publication 3');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'about','My background','I earned my degree in Electronic & Computer Engineering from Lagos State University, graduating with highest honors. That foundation shapes how I approach software, machine learning, and the physical systems they connect to.','','','','',11,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='about' and title='My background');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'about','What I’m drawn to','My work sits at the intersection of machine learning, software, and research. I’m interested in intelligent, energy-aware systems, with research interests in autonomous systems, robot learning, embodied AI, and trustworthy AI.','','','','',12,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='about' and title='What I’m drawn to');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'about','What matters to me','I have led educational programs and community outreach, and I advocate for AI for Social Good. I care about sharing knowledge and exploring how technology can help people.','','','','',13,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='about' and title='What matters to me');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'about','Beyond the work','Outside research, I follow current events, watch football, study blockchain, and play snooker. These interests give me space to explore, reflect, and see things from a different perspective.','','','','',14,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='about' and title='Beyond the work');
insert into public.portfolio_content (kind,title,body,url,image,author,date,position,published,categories) select 'intro','Research Engineer & Applied AI Engineer','I am on a mission of democratizing the ethical usage of artificial intelligence and super intelligence in under-represented, under-developed and developed countries in Africa. My research interests are in Trustworthy AI, Responsible AI and all things about Machine Intelligence.','','','','',0,true,array[]::text[] where not exists (select 1 from public.portfolio_content where kind='intro' and title='Research Engineer & Applied AI Engineer');
